// Turns the rulebook (packages/core/rules/*.md) into a TypeScript module, so
// that core can ship it to browsers, which cannot read files. The version is a
// fingerprint of the text: any edit changes it, and the edit log records it.
//
// Run: corepack pnpm rules. A test fails when the generated file is stale.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const dir = fileURLToPath(new URL('../packages/core/rules/', import.meta.url))
const out = fileURLToPath(new URL('../packages/core/src/ai/rulebook.generated.ts', import.meta.url))

export function rulebook() {
  const topics = Object.fromEntries(
    readdirSync(dir)
      .filter((file) => file.endsWith('.md'))
      .sort()
      .map((file) => [file.slice(0, -3), readFileSync(dir + file, 'utf8').replace(/\r\n/g, '\n').trimEnd()]),
  )
  return { version: fingerprint(JSON.stringify(topics)), topics }
}

/** FNV-1a, 32 bits, as 8 hex characters. */
function fingerprint(text) {
  let hash = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i)
    hash = Math.imul(hash, 0x01000193) >>> 0
  }
  return hash.toString(16).padStart(8, '0')
}

export function render({ version, topics }) {
  return `// Generated by scripts/build-rules.mjs from packages/core/rules/*.md. Do not edit.
export const RULEBOOK = {
  version: ${JSON.stringify(version)},
  topics: {
${Object.entries(topics)
  .map(([name, text]) => `    ${name}: ${JSON.stringify(text)},`)
  .join('\n')}
  },
} as const
`
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(out, render(rulebook()))
  console.log(`Wrote ${out}`)
}
